create role authenticated nologin; create role anon nologin; create role service_role nologin bypassrls;
create schema auth; create schema storage;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claim.role', true),'') $$;
grant usage on schema auth, public, storage to authenticated, anon, service_role;
grant execute on all functions in schema auth to authenticated, anon, service_role;
create table storage.buckets (id text primary key, public boolean, file_size_limit bigint, allowed_mime_types text[]);
insert into storage.buckets values ('avatars',true,null,null),('community-uploads',true,null,null),('community-videos',true,52428800,null);
create type point_source as enum ('signup_bonus','challenge','reward_redemption','badge');
create type community_post_kind as enum ('post','announcement','poll','challenge');
create table fans (id uuid primary key, first_name text, last_name text, city text, handle text, interest text, music_outlet text, phone text, socials jsonb, total_points int default 0);
create table fan_community_memberships (fan_id uuid references fans(id) on delete cascade, community_id text, subscription_tier text default 'free', founding_fan_number int, total_points int default 0, primary key (fan_id, community_id));
create table admin_users (user_id uuid, community_id text);
create table points_ledger (id uuid primary key default gen_random_uuid(), fan_id uuid references fans(id) on delete cascade, delta int, source point_source, source_ref text, community_id text not null, note text, multiplier numeric, created_at timestamptz default now());
create table community_posts (id uuid primary key default gen_random_uuid(), artist_slug text, author_id uuid references fans(id) on delete cascade, kind community_post_kind default 'post', title text, body text, image_url text, pinned boolean default false, created_at timestamptz default now(), community_id text, visibility text default 'public', moderation_status text default 'pending', moderation_severity smallint, moderation_categories text[], moderation_reason text, moderation_self_harm boolean default false, moderation_classified_at timestamptz, moderation_model text, moderation_prompt_version text, tags text[] default '{}', tagged_at timestamptz, tag_model text, tag_prompt_version text, correct_option_id uuid, resolved_at timestamptz, points_for_correct int, prediction_closes_at timestamptz, duplicate_of uuid, thread_summary text, thread_summary_count int, thread_summary_at timestamptz, image_alt text, moderation_user_message text, scheduled_for timestamptz, announced_at timestamptz, submit_key uuid);
create table community_comments (id uuid primary key default gen_random_uuid(), post_id uuid references community_posts(id) on delete cascade, author_id uuid references fans(id) on delete cascade, body text, created_at timestamptz default now(), moderation_status text default 'pending', moderation_severity smallint, moderation_categories text[], moderation_reason text, moderation_self_harm boolean default false, moderation_classified_at timestamptz, moderation_model text, moderation_prompt_version text, draft_used boolean default false);
create table community_reactions (post_id uuid references community_posts(id) on delete cascade, fan_id uuid, emoji text, created_at timestamptz default now(), primary key (post_id, fan_id, emoji));
create table reward_redemptions (id uuid primary key default gen_random_uuid(), fan_id uuid, reward_id uuid, community_id text, point_cost int, delivery_details text, status text default 'pending');
create table community_challenge_entries (id uuid primary key default gen_random_uuid(), post_id uuid, fan_id uuid, body text);
grant select, insert, update, delete on all tables in schema public to authenticated, anon, service_role;
create function is_admin_of(p_community_id text) returns boolean language sql stable security definer set search_path to 'public' as $$ select exists (select 1 from admin_users where user_id = auth.uid() and (community_id = p_community_id or community_id = '*')) $$;
create function is_premium(p_fan_id uuid, p_community_id text) returns boolean language sql stable security definer set search_path to 'public' as $$ select exists (select 1 from fan_community_memberships where fan_id = p_fan_id and community_id = p_community_id and subscription_tier in ('premium','comped','past_due')) $$;
revoke execute on function is_premium(uuid,text) from public;
create function can_read_post_visibility(p_visibility text, p_artist_slug text) returns boolean language sql stable security definer set search_path to 'public' as $$ select case when p_visibility is null or p_visibility='public' then true when auth.uid() is null then false when p_visibility='premium' then public.is_premium(auth.uid(), p_artist_slug) else false end $$;
create function community_post_visible_to_viewer(p_post_id uuid) returns boolean language sql stable security definer set search_path to 'public' as $$ select exists (select 1 from public.community_posts p where p.id = p_post_id and ((auth.uid() is not null and p.author_id = auth.uid()) or public.is_admin_of(p.artist_slug) or (p.moderation_status in ('pending','safe','flag_review') and (p.scheduled_for is null or p.scheduled_for <= now()) and public.can_read_post_visibility(p.visibility, p.artist_slug)))) $$;
create function activity_day_start() returns timestamptz language sql stable as $$ select (date_trunc('day', timezone('America/New_York', now())) at time zone 'America/New_York') $$;
create function fan_ledger_balance(p_fan_id uuid) returns int language sql stable security definer set search_path to 'public' as $$ select coalesce(sum(delta),0)::int from points_ledger where fan_id = p_fan_id $$;
revoke execute on function fan_ledger_balance(uuid) from public;
create function points_multiplier(p_fan_id uuid, p_community_id text) returns numeric language sql stable security definer set search_path to 'public' as $$ select 1::numeric $$;
create function sync_points_from_ledger(p_fan_id uuid) returns int language plpgsql security definer set search_path to 'public' as $$ declare v int; begin select coalesce(sum(delta),0) into v from points_ledger where fan_id=p_fan_id; update fans set total_points=v where id=p_fan_id; return v; end $$;
create function apply_points_award(p_fan_id uuid, p_base_delta integer, p_source text, p_source_ref text, p_community_id text default null, p_note text default null) returns integer language plpgsql security definer set search_path to 'public' as $function$
declare v_mult numeric := 1; v_delta integer; v_note text := p_note; v_source point_source;
begin
  if p_fan_id is null or p_base_delta is null or p_base_delta = 0 then return 0; end if;
  begin v_source := p_source::point_source; exception when invalid_text_representation then v_source := 'challenge'; end;
  perform 1 from public.fans where id = p_fan_id for update;
  if not found then raise exception 'Fan not found'; end if;
  if p_source_ref is not null and exists (select 1 from public.points_ledger where source_ref = p_source_ref) then return 0; end if;
  if p_base_delta > 0 and p_community_id is not null and v_source <> 'reward_redemption' then v_mult := public.points_multiplier(p_fan_id, p_community_id); end if;
  if p_base_delta < 0 then v_delta := p_base_delta; v_mult := 1; else v_delta := round(p_base_delta * v_mult)::integer; end if;
  insert into public.points_ledger (fan_id, delta, source, source_ref, community_id, note, multiplier) values (p_fan_id, v_delta, v_source, p_source_ref, p_community_id, v_note, v_mult);
  perform public.sync_points_from_ledger(p_fan_id);
  return v_delta;
end $function$;
revoke execute on function apply_points_award(uuid,integer,text,text,text,text) from public;
create function award_community_post_points() returns trigger language plpgsql security definer set search_path to 'public' as $$ begin perform public.apply_points_award(new.author_id, 5, 'challenge', 'community_post:' || new.id::text, new.artist_slug, 'Community post'); return new; end $$;
create function try_award_comment_points(p_comment_id uuid) returns boolean language plpgsql security definer set search_path to 'public' as $$ declare v_author uuid; v_slug text; v_ref text := 'community_comment:' || p_comment_id::text; v_today int; begin select c.author_id, p.artist_slug into v_author, v_slug from community_comments c join community_posts p on p.id=c.post_id where c.id=p_comment_id; if v_author is null then return false; end if; if exists (select 1 from points_ledger where source_ref=v_ref) then return false; end if; select count(*) into v_today from points_ledger where fan_id=v_author and source_ref like 'community_comment:%' and created_at >= public.activity_day_start(); if v_today >= 5 then return false; end if; return public.apply_points_award(v_author, 10, 'challenge', v_ref, v_slug, 'Community comment') <> 0; end $$;
create function award_community_comment_points() returns trigger language plpgsql security definer set search_path to 'public' as $$ begin perform public.try_award_comment_points(new.id); return new; end $$;
create function set_community_id_from_parent() returns trigger language plpgsql security definer set search_path to 'public' as $$ begin if new.community_id is null then new.community_id := new.artist_slug; end if; return new; end $$;
create trigger community_posts_set_community_id before insert on community_posts for each row execute function set_community_id_from_parent('artist_slug');
create trigger community_posts_award_points after insert on community_posts for each row execute function award_community_post_points();
create trigger community_comments_award_points after insert on community_comments for each row execute function award_community_comment_points();
alter table community_posts enable row level security; alter table community_comments enable row level security; alter table community_reactions enable row level security;
create policy community_posts_public_read on community_posts for select using (true);
create policy community_posts_insert on community_posts for insert with check (auth.uid() = author_id);
create policy community_posts_update on community_posts for update using (auth.uid() = author_id);
create policy community_posts_delete on community_posts for delete using (auth.uid() = author_id);
create policy community_comments_read on community_comments for select using (true);
create policy community_comments_insert on community_comments for insert with check (auth.uid() = author_id);
create policy community_comments_delete on community_comments for delete using (auth.uid() = author_id);
create policy community_reactions_select on community_reactions for select using (true);
create policy community_reactions_insert on community_reactions for insert with check (auth.uid() = fan_id);
create policy community_reactions_delete on community_reactions for delete using (auth.uid() = fan_id);
